use soroban_sdk::contracttype;
use sororail_common::impl_single_position_storage;

use crate::types::Grant;

/// Storage keys for the vesting contract.
///
/// The whole grant lives in **instance** storage, so it shares one TTL with
/// the contract. The enum has one variant because one instance holds one
/// grant. It is typed so the key encodes the same way across every SoroRail
/// contract.
///
/// Access goes through the helpers generated by
/// `impl_single_position_storage!`, which extend the TTL on every write.
#[contracttype]
pub enum DataKey {
    /// The single grant held by this instance.
    ///
    /// Holds the full [`Grant`] record: parties, schedule (`start`, `cliff`,
    /// `duration`), `total`, the `claimed` and `returned` totals, and whether
    /// the grant has been revoked. Vested amounts are derived from these fields
    /// on each read rather than stored.
    /// Absent until `create` runs, which is what `NotInitialized` reports.
    Grant,
}

impl_single_position_storage!(Grant, DataKey::Grant);
